<template>
  <div ref="libraryRef" class="library" :class="{'is-reading':fullScreen,'is-resizing':sidebarDragging}">
    <aside v-if="!fullScreen" class="library-sidebar" :style="{width:sidebarWidth+'px'}">
      <div class="sidebar-search"><i class="fa-solid fa-magnifying-glass"></i><input v-model="search" aria-label="搜索空间资料" placeholder="搜索资料、日报…" @input="searchDocuments" /></div>
      <div class="library-label"><span><i class="fa-solid fa-layer-group"></i> 资料空间</span><button aria-label="备份资料库" title="备份整个资料库" @click="backupLibrary"><i class="fa-solid fa-download"></i></button><button aria-label="恢复资料库备份" title="恢复资料库备份" @click="restoreLibrary"><i class="fa-solid fa-clock-rotate-left"></i></button><button aria-label="新建空间" title="新建空间" @click="ask('space')"><i class="fa-solid fa-plus"></i></button></div>
      <nav class="space-tree" aria-label="资料空间和文件">
        <section v-for="space in spaces" :key="space.id" class="space-group">
          <div class="space-button" @click="openSpace(space.id)" @contextmenu.prevent="showSpaceMenu($event,space.id)" :class="{active:spaceId===space.id&&!folderId&&!selected&&!trashView}">
            <button class="space-expand" :aria-label="(expandedSpaces.has(space.id)?'收起':'展开')+space.title" :aria-expanded="expandedSpaces.has(space.id)" @click.stop="toggleSpace(space.id)"><i :class="expandedSpaces.has(space.id)?'fa-solid fa-chevron-down':'fa-solid fa-chevron-right'"></i></button>
            <button class="space-select" :title="space.title" @click.stop="openSpace(space.id)"><i class="fa-solid fa-folder-open"></i><span>{{space.title}}</span></button>
            <button class="tree-add" :aria-label="'在'+space.title+'中新建'" title="新建文件或文件夹" @click.stop="openTreeMenu(space.id,null)"><i class="fa-solid fa-plus"></i></button><button class="tree-add" :aria-label="space.title+'的更多操作'" title="更多：重命名、删除空间" @click.stop="showEntryMenu($event,{...space,kind:'space'})"><i class="fa-solid fa-ellipsis"></i></button>
          </div>
          <div v-if="expandedSpaces.has(space.id)" class="space-children">
            <div v-for="row in treeRows(space.id)" :key="row.id" class="tree-row" @click="openTreeItem(row)" @contextmenu.prevent="showEntryMenu($event,row)" :class="{active:spaceId===space.id&&!trashView&&(selected?.id===row.id||(!selected&&folderId===row.id))}" :style="{paddingLeft:8+row.depth*12+'px'}">
              <button v-if="row.kind==='folder'" class="tree-expand" :aria-label="(expanded.has(row.id)?'收起':'展开')+row.title" :aria-expanded="expanded.has(row.id)" @click.stop="toggleFolder(row.id)"><i :class="expanded.has(row.id)?'fa-solid fa-chevron-down':'fa-solid fa-chevron-right'"></i></button>
              <span v-else class="tree-leaf-indent"></span>
              <button class="tree-select" :title="row.title" @click.stop="openTreeItem(row)"><i :class="icon(row)"></i><span>{{row.title}}</span></button>
              <button v-if="row.kind==='folder'" class="tree-add" :aria-label="'在'+row.title+'中新建'" title="新建文件或子文件夹" @click.stop="openTreeMenu(space.id,row.id)"><i class="fa-solid fa-plus"></i></button><button class="tree-add" :aria-label="row.title+'的更多操作'" title="更多：重命名、移动、删除" @click.stop="showEntryMenu($event,row)"><i class="fa-solid fa-ellipsis"></i></button>
            </div>
            <span v-if="!treeRows(space.id).length" class="space-empty">暂无资料，点击 + 添加</span>
          </div>
        </section>
      </nav>
      <button class="trash-button" :class="{active:trashView}" @click="showTrash"><i class="fa-regular fa-trash-can"></i>回收站</button>
      <RouterLink to="/knowledge" class="handbook-link"><i class="fa-solid fa-book-open"></i> FDE 作战手册 <i class="fa-solid fa-arrow-up-right-from-square"></i></RouterLink>
    </aside>
    <div v-if="!fullScreen" class="library-splitter" role="separator" aria-label="调整目录与预览宽度" aria-orientation="vertical" tabindex="0" :aria-valuenow="sidebarWidth" :aria-valuemin="sidebarMinWidth" :aria-valuemax="sidebarMaxWidth" title="左右拖动调整宽度，双击恢复默认" @pointerdown="startSidebarResize" @pointermove="moveSidebarResize" @pointerup="endSidebarResize" @pointercancel="endSidebarResize" @lostpointercapture="sidebarDragging=false" @dblclick="resetSidebarWidth" @keydown.left.prevent="setSidebarWidth(sidebarWidth-24)" @keydown.right.prevent="setSidebarWidth(sidebarWidth+24)"></div>
    <main class="library-main">

      <p v-if="error" class="library-error" role="alert">{{error}}<button @click="error=''" aria-label="关闭提示">×</button></p>
      <p v-if="notice" class="library-notice" role="status"><i class="fa-solid fa-circle-check"></i>{{notice}}<button aria-label="关闭操作提示" @click="notice=''">×</button></p>
      <LibraryDocument v-if="selected" ref="documentRef" :key="selected.id" :item="selected" :auto-edit="newDocumentId===selected.id" @saved="refresh"><template #navigation><button @click="closeDocument" aria-label="返回资料列表" title="返回资料列表"><i class="fa-solid fa-arrow-left"></i></button><span class="document-location">{{currentSpace?.title}}<template v-for="part in breadcrumbs" :key="part.id"> / {{part.title}}</template><template v-if="selected.kind!=='folder'"> / {{selected.title}}</template></span></template><template #view-actions><button @click="fullScreen=!fullScreen" :title="fullScreen?'退出全屏':'全屏阅读'"><i :class="fullScreen?'fa-solid fa-compress':'fa-solid fa-expand'"></i></button></template><template #related-files="{editing}"><section v-if="selected.kind==='folder'&&!editing" class="folder-contents"><header><h2>文件夹里的资料</h2><span>{{ folderFiles.length }} 份资料 · 含子文件夹</span></header><p v-if="!folderContents.length" class="folder-empty">此文件夹暂无资料</p><button v-for="item in folderContents" :key="item.id" class="folder-content-row" @click="openItem(item)" :title="folderPath(item)+' / '+item.title"><i :class="icon(item)"></i><span><strong>{{item.title}}</strong><small>{{item.kind==='folder'?folderSummary(item):folderPath(item)}}</small></span><em>{{typeLabel(item)}}</em><i class="fa-solid fa-chevron-right"></i></button></section></template></LibraryDocument>
      <section v-else class="library-browser">
        <div v-if="!trashView&&!folderId&&!search" class="space-intro"><div class="space-mark"><i class="fa-solid fa-folder-open"></i></div><div><h2>{{currentSpace?.title}}</h2><p>{{currentSpace?.description}}</p></div><span>{{ countFiles }} 份资料</span></div>
        <div class="list-toolbar"><div class="list-filters"><button v-for="filter in filters" :key="filter.id" :class="{active:fileFilter===filter.id}" @click="fileFilter=filter.id">{{filter.label}}</button></div><UiSelect field v-model="sort" aria-label="资料排序" :options="[{ value: 'updated', label: '最近更新' }, { value: 'title', label: '按名称' }]" /></div>
        <div v-if="loading||searchBusy" class="empty-state"><i class="fa-solid fa-spinner fa-spin"></i><p>{{searchBusy?'正在搜索正文…':'正在读取资料…'}}</p></div>
        <div v-else-if="!visibleEntries.length" class="empty-state"><i class="fa-regular fa-folder-open"></i><h3>{{search?'没有找到资料':trashView?'回收站为空':'把材料放进这里'}}</h3><p>{{search?'试试其他关键词':trashView?'移入回收站的资料可以恢复':'上传 Word、表格、PDF、图片、视频等文件，或新建一份日报。'}}</p><button v-if="!search&&!trashView" class="primary" @click="upload"><i class="fa-solid fa-arrow-up-from-bracket"></i>上传资料</button></div>
        <div v-else class="file-list" role="list">
          <div class="list-heading"><span>名称</span><span>类型</span><span>最近更新</span><span></span></div>
          <div v-for="item in visibleEntries" :key="item.id" class="file-row" role="listitem">
            <button class="file-name" :title="item.title" :disabled="trashView" @click="openItem(item)"><span class="file-icon" :class="item.kind"><i :class="icon(item)"></i></span><span><strong>{{item.title}}</strong><small v-if="search">{{folderPath(item)}} · {{searchMatches?.find(m=>m.id===item.id)?.snippet}}</small><small v-else-if="item.kind==='folder'">{{folderSummary(item)}}</small><small v-else :title="folderPath(item)">{{folderPath(item)}}<template v-if="item.sourceUrl"> · 来自极库云</template></small></span></button>
            <span class="file-type">{{typeLabel(item)}}</span><time>{{formatTime(item.updatedAt)}}</time>
            <div class="row-actions"><button v-if="trashView" @click="restore(item)" title="恢复资料"><i class="fa-solid fa-rotate-left"></i></button><template v-else><button @click="ask('rename',item)" title="重命名"><i class="fa-solid fa-pen"></i></button><button @click="ask('move',item)" title="移动到文件夹"><i class="fa-solid fa-folder-tree"></i></button><button @click="trash(item)" title="移入回收站"><i class="fa-regular fa-trash-can"></i></button></template></div>
          </div>
        </div>
      </section>
    </main>
    <div v-if="entryMenu" class="entry-menu-backdrop" @click.self="entryMenu=null"><div class="entry-menu" role="menu" :style="{left:entryMenu.x+'px',top:entryMenu.y+'px'}"><button role="menuitem" @click="entryAction('rename')"><i class="fa-solid fa-pen"></i>重命名</button><button v-if="entryMenu.item.kind!=='space'" role="menuitem" @click="entryAction('move')"><i class="fa-solid fa-folder-tree"></i>移动到文件夹</button><button role="menuitem" class="delete-entry" @click="entryAction('trash')"><i class="fa-regular fa-trash-can"></i>删除 <small>移入回收站</small></button></div></div>
    <div v-if="treeMenu" class="tree-menu-backdrop" @click.self="treeMenu=null"><div class="tree-create-menu" role="dialog" aria-label="新建资料"><header><span>添加到 {{currentFolder?.title || currentSpace?.title}}</span><button aria-label="关闭新建菜单" @click="treeMenu=null">×</button></header><button @click="ask('folder')"><i class="fa-solid fa-folder-plus"></i>文件夹</button><button @click="ask('document')"><i class="fa-solid fa-file-word"></i>Word 文档</button><button @click="ask('daily')"><i class="fa-regular fa-calendar-check"></i>工作日报</button><button @click="ask('text')"><i class="fa-solid fa-file-lines"></i>文本文件</button><button @click="ask('link')"><i class="fa-solid fa-link"></i>网页链接</button><button @click="treeMenu=null;upload()"><i class="fa-solid fa-arrow-up-from-bracket"></i>上传文件</button></div></div>
    <div v-if="modal" class="library-modal-backdrop" @click.self="modal=null"><form class="library-modal" @submit.prevent="submit"><h2>{{modalTitle}}</h2><label v-if="modal.kind!=='move'">名称<input ref="nameInput" v-model="name" required autofocus placeholder="输入名称" /></label><label v-if="modal.kind==='link'">链接<input v-model="link" type="url" required placeholder="https://…" /></label><label v-if="modal.kind==='move'">目标文件夹<UiSelect field v-model="destination" :options="[{ value: '', label: '空间根目录' }, ...(availableFolders).map((f) => ({ value: f.id, label: String(folderPath(f)) + ' / ' + String(f.title) }))]" /></label><p v-if="modal.kind==='daily'">自动生成「今日完成、问题与风险、明日计划」，可以直接编辑。</p><p v-if="modal.kind==='space'">为新的项目或业务建立独立的资料空间。</p><div><button type="button" @click="modal=null">取消</button><button class="primary" :disabled="busy">{{busy?'处理中…':modal.kind==='rename'?'保存':'确定'}}</button></div></form></div>
  </div>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router';
import LibraryDocument from './LibraryDocument.vue';
const route=useRoute(),router=useRouter();
const libraryRef=ref(null),sidebarWidth=ref(266),sidebarDragging=ref(false),layoutWidth=ref(1200);
const sidebarMinWidth=computed(()=>Math.min(240,Math.max(140,layoutWidth.value-360)));
const sidebarMaxWidth=computed(()=>Math.max(sidebarMinWidth.value,Math.min(720,layoutWidth.value*.5,layoutWidth.value-360)));
const sidebarRatioKey='fde.library.sidebar-ratio';
let sidebarRatio=null,sidebarObserver,sidebarDragStartX=0,sidebarDragStartWidth=0;
try{const saved=Number(localStorage.getItem(sidebarRatioKey));if(saved>0&&saved<1)sidebarRatio=saved;}catch(_){/* 存储不可用时仍可调整宽度。 */}
function setSidebarWidth(width,remember=true){
  sidebarWidth.value=Math.round(Math.min(sidebarMaxWidth.value,Math.max(sidebarMinWidth.value,width)));
  if(remember){sidebarRatio=sidebarWidth.value/layoutWidth.value;try{localStorage.setItem(sidebarRatioKey,String(sidebarRatio));}catch(_){}}
}
function resetSidebarWidth(){sidebarRatio=null;try{localStorage.removeItem(sidebarRatioKey);}catch(_){}setSidebarWidth(layoutWidth.value<=1100?230:266,false);}
function startSidebarResize(event){if(event.button!==0)return;event.preventDefault();sidebarDragStartX=event.clientX;sidebarDragStartWidth=sidebarWidth.value;sidebarDragging.value=true;event.currentTarget.setPointerCapture(event.pointerId);}
function moveSidebarResize(event){if(sidebarDragging.value)setSidebarWidth(sidebarDragStartWidth+event.clientX-sidebarDragStartX,false);}
function endSidebarResize(event){if(!sidebarDragging.value)return;sidebarDragging.value=false;setSidebarWidth(sidebarWidth.value);if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);}
const spaces=ref([]),deletedSpaces=ref([]),entries=ref([]),spaceId=ref(String(route.query.space||'agents')),folderId=ref(null),selected=ref(null),search=ref(''),fileFilter=ref('all'),sort=ref('updated'),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),newMenu=ref(false),trashView=ref(false),fullScreen=ref(false),expanded=ref(new Set()),expandedSpaces=ref(new Set([spaceId.value])),newDocumentId=ref(null),treeMenu=ref(null),entryMenu=ref(null),modal=ref(null),name=ref(''),link=ref(''),destination=ref(''),nameInput=ref(null),documentRef=ref(null);
const filters=[{id:'all',label:'全部'},{id:'documents',label:'文档'},{id:'daily',label:'日报 / 周报'},{id:'files',label:'附件'}];
const currentSpace=computed(()=>spaces.value.find(s=>s.id===spaceId.value)),currentFolder=computed(()=>entries.value.find(e=>e.id===folderId.value)),spaceEntries=computed(()=>entries.value.filter(e=>e.spaceId===spaceId.value)),countFiles=computed(()=>spaceEntries.value.filter(e=>e.kind!=='folder'&&!e.deletedAt).length);
const breadcrumbs=computed(()=>{const list=[];let f=currentFolder.value;const visited=new Set();while(f&&!visited.has(f.id)){visited.add(f.id);list.unshift(f);f=entries.value.find(e=>e.id===f.parentId);}return list;});
function treeRows(id){const rows=[],query=search.value.trim().toLowerCase();const items=entries.value.filter(e=>e.spaceId===id&&!e.deletedAt);const included=new Set();if(query){for(const item of items.filter(e=>e.title.toLowerCase().includes(query))){included.add(item.id);let parent=items.find(e=>e.id===item.parentId);while(parent&&!included.has(parent.id)){included.add(parent.id);parent=items.find(e=>e.id===parent.parentId);}}}
  const walk=(parentId,depth)=>{const children=items.filter(e=>(e.parentId||null)===parentId&&(!query||included.has(e.id))).sort((a,b)=>Number(b.kind==='folder')-Number(a.kind==='folder')||a.title.localeCompare(b.title,'zh'));for(const e of children){rows.push({...e,depth});if(e.kind==='folder'&&(query||expanded.value.has(e.id)))walk(e.id,depth+1);}};walk(null,0);return rows;}
function toggleSpace(id){const set=new Set(expandedSpaces.value);set.has(id)?set.delete(id):set.add(id);expandedSpaces.value=set;}
async function openSpace(id){const wasOpen=expandedSpaces.value.has(id);await selectSpace(id);if(wasOpen&&spaceId.value===id)expandedSpaces.value.delete(id);}
async function openTreeItem(item){if(selected.value?.id===item.id){if(item.kind==='folder')toggleFolder(item.id);return;}if(!await mayLeave())return;const wasOpen=expanded.value.has(item.id);await openItem(item,true);if(item.kind==='folder'&&wasOpen)expanded.value.delete(item.id);}
function showEntryMenu(event,item){entryMenu.value={item,x:Math.max(8,Math.min(event.clientX,window.innerWidth-210)),y:Math.max(8,Math.min(event.clientY,window.innerHeight-170))};}
function showSpaceMenu(event,id){showEntryMenu(event,{...spaces.value.find(s=>s.id===id),kind:'space'});}
async function entryAction(action){const item=entryMenu.value.item;entryMenu.value=null;if(action==='trash')await trash(item);else await ask(item.kind==='space'?'rename-space':action,item);}
async function openTreeMenu(id,parentId){if(!await mayLeave())return;spaceId.value=id;folderId.value=parentId;selected.value=null;trashView.value=false;fullScreen.value=false;expandedSpaces.value.add(id);if(parentId)expanded.value.add(parentId);treeMenu.value={spaceId:id,parentId};newMenu.value=false;}
const searchMatches=ref(null),searchBusy=ref(false);let searchTimer,searchSeq=0;
async function searchDocuments(){if(selected.value){if(!await mayLeave()){search.value='';return;}selected.value=null;fullScreen.value=false;}if(search.value)spaces.value.forEach(s=>expandedSpaces.value.add(s.id));clearTimeout(searchTimer);const seq=++searchSeq;searchMatches.value=null;if(search.value.trim()){searchBusy.value=true;searchTimer=setTimeout(async()=>{try{const result=await call(window.api.library.search(search.value.trim(),spaceId.value));if(seq===searchSeq)searchMatches.value=result.matches;}catch(e){if(seq===searchSeq)error.value=e.message;}finally{if(seq===searchSeq)searchBusy.value=false;}},300);}else searchBusy.value=false;}
// 目录折叠仅控制左侧树；右侧始终列出当前范围内各级目录里的文件。
const activeSpaceEntries=computed(()=>spaceEntries.value.filter(e=>!e.deletedAt));
function descendants(id){
  const result=[],visited=new Set([id]),queue=[id];
  const children=new Map();
  for(const item of activeSpaceEntries.value){const key=item.parentId||null;if(!children.has(key))children.set(key,[]);children.get(key).push(item);}
  for(let i=0;i<queue.length;i++)for(const item of children.get(queue[i])||[]){if(visited.has(item.id))continue;visited.add(item.id);result.push(item);if(item.kind==='folder')queue.push(item.id);}
  return result;
}
function listScope(id){const items=id?descendants(id):activeSpaceEntries.value;return items.filter(e=>e.kind!=='folder'||(e.parentId||null)===(id||null));}
function sortEntries(items){return items.sort((a,b)=>sort.value==='title'?a.title.localeCompare(b.title,'zh'):Number(b.kind==='folder')-Number(a.kind==='folder')||b.updatedAt.localeCompare(a.updatedAt));}
function folderSummary(item){const items=descendants(item.id);return `${items.filter(e=>e.kind!=='folder').length} 份资料 · ${items.filter(e=>e.kind==='folder').length} 个子文件夹`;}
const folderFiles=computed(()=>selected.value?.kind==='folder'?descendants(selected.value.id).filter(e=>e.kind!=='folder'):[]);
const folderContents=computed(()=>selected.value?.kind==='folder'?sortEntries(listScope(selected.value.id)):[]);
const visibleEntries=computed(()=>{
  const items=trashView.value?[...entries.value.filter(e=>e.deletedAt),...deletedSpaces.value.map(s=>({...s,kind:'space',spaceId:s.id,updatedAt:s.deletedAt}))]:search.value?activeSpaceEntries.value:listScope(folderId.value);
  return sortEntries(items.filter(e=>!search.value||(searchMatches.value?searchMatches.value.some(m=>m.id===e.id):e.title.toLowerCase().includes(search.value.toLowerCase()))).filter(e=>fileFilter.value==='all'||(fileFilter.value==='documents'&&['document','daily'].includes(e.kind)||fileFilter.value==='documents'&&['docx','md','txt'].includes(e.ext))||(fileFilter.value==='daily'&&(/日报|周报/.test(e.title)||e.kind==='daily'))||(fileFilter.value==='files'&&e.kind==='file')));
});
const modalTitle=computed(()=>({space:'新建资料空间',folder:'新建文件夹',document:'新建 Word 文档',daily:'新建工作日报',text:'新建文本文件',link:'添加网页链接',rename:'重命名','rename-space':'重命名空间',move:'移动资料'}[modal.value?.kind]));
const availableFolders=computed(()=>spaceEntries.value.filter(e=>e.kind==='folder'&&!e.deletedAt&&e.id!==modal.value?.item?.id));
const mayLeave=async()=>!documentRef.value||await documentRef.value.beforeLeave();
async function call(promise){const res=await promise;if(!res?.success)throw Error(res?.error||'操作失败');return res;}
async function refresh(){try{const data=await call(window.api?.library?.list?.());spaces.value=data.spaces.filter(s=>!s.deletedAt);deletedSpaces.value=data.spaces.filter(s=>s.deletedAt);entries.value=data.entries;if(!currentSpace.value)spaceId.value=spaces.value[0]?.id;}catch(e){error.value=window.api?.library?e.message:'请在 FDE 桌面窗口中使用资料库。';}finally{loading.value=false;}}
async function selectSpace(id){if(!await mayLeave())return;spaceId.value=id;expandedSpaces.value.add(id);folderId.value=null;selected.value=null;trashView.value=false;search.value='';fullScreen.value=false;fileFilter.value='all';router.replace({path:'/library',query:{space:id}});}
async function goFolder(id){if(id){const item=entries.value.find(e=>e.id===id&&!e.deletedAt);if(item)await openItem(item);return;}await selectSpace(spaceId.value);}
async function showTrash(){if(!await mayLeave())return;selected.value=null;trashView.value=true;search.value='';fileFilter.value='all';}
function toggleFolder(id){const s=new Set(expanded.value);s.has(id)?s.delete(id):s.add(id);expanded.value=s;}
async function openItem(item,leaveChecked=false){if(selected.value?.id===item.id)return;if(!leaveChecked&&!await mayLeave())return;spaceId.value=item.spaceId;expandedSpaces.value.add(item.spaceId);selected.value=item;folderId.value=item.kind==='folder'?item.id:item.parentId||null;trashView.value=false;search.value='';for(const part of breadcrumbs.value)expanded.value.add(part.id);router.replace({path:'/library',query:{space:item.spaceId,file:item.id}});}
async function closeDocument(){if(!await mayLeave())return;selected.value=null;fullScreen.value=false;router.replace({path:'/library',query:{space:spaceId.value}});}
async function ask(kind,item){treeMenu.value=null;newMenu.value=false;modal.value={kind,item};name.value=item?.title||(kind==='daily'?new Date().toLocaleDateString('sv-SE')+' 工作日报':'');link.value='';destination.value='';await nextTick();nameInput.value?.focus();}
