function typeLabel(e){return e.kind==='space'?'资料空间':e.kind==='folder'?'文件夹':e.kind==='link'?'云文档 / 链接':e.kind==='daily'?'日报':e.ext==='docx'?'Word 文档':e.ext?.toUpperCase()||'文档';}
